mapper.select:
SELECT status, COUNT(*) AS n From t_after_sale WHERE 1=1
AND user_id = #{userId}
GROUP BY status

SELECT a.ticket_no, a.order_no, a.user_id, a.type, a.reason, a.status, a.source, a.handler_id, a.handle_remark, a.ai_generated, a.ai_confidence, a.create_time, a.update_time, i.product_id, i.product_name, u1.nickname AS user_name, u2.nickname AS handler_name FROM t_after_sale a LEFT JOIN t_order_item i ON a.order_item_id = i.id LEFT JOIN t_user u1 ON a.user_id = u1.id LEFT JOIN t_user u2 ON a.handler_id = u2.id WHERE 1 = 1
AND a.user_id = #{userId}
AND a.status = #{status}
AND a.source = #{source}
AND ( a.ticket_no LIKE CONCAT('%', #{keyword}, '%') OR a.order_no LIKE CONCAT('%', #{keyword}, '%') OR i.product_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY a.create_time DESC
